package com.credflow.eligibility.api;
import java.util.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.credflow.platform.persistence.DatabaseAccess;import org.springframework.security.oauth2.jwt.Jwt;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class LenderRulesServiceTest {
 LenderRulesInput input(String min,String max,String returns){return new LenderRulesInput(1,"Test product",12,"100000.00",returns,min,max,"1.0000",null,true,Set.of("WORKING_CAPITAL"),"Verification");}
 @Test void validatesRangesAndPercentages(){assertDoesNotThrow(()->LenderRulesService.validate(input("100000.00","200000.00","10")));assertThrows(Exception.class,()->LenderRulesService.validate(input("200000.00","100000.00","10")));assertThrows(Exception.class,()->LenderRulesService.validate(input("0","200000.00","10")));assertThrows(Exception.class,()->LenderRulesService.validate(input("100000.00","200000.00","100.0001")));}
 @Test void sellerCannotReadOrModifyRules(){var db=mock(DatabaseAccess.class);var service=new LenderRulesService(db,new ObjectMapper());var jwt=Jwt.withTokenValue("unit").header("alg","RS256").subject("seller").claim("roles",List.of("SELLER")).build();assertThrows(Exception.class,()->service.list(jwt));assertThrows(Exception.class,()->service.update(UUID.randomUUID(),input("1","2","5"),UUID.randomUUID().toString(),jwt));verifyNoInteractions(db);}

 Jwt officer(String id){return Jwt.withTokenValue("unit").header("alg","RS256").subject("officer").claim("roles",List.of("LENDER_OFFICER")).claim("lenderId",id).build();}
 @Test void adminCannotReadHistoryOrModifyRules(){var db=mock(DatabaseAccess.class);var s=new LenderRulesService(db,new ObjectMapper());var jwt=Jwt.withTokenValue("unit").header("alg","RS256").subject("admin").claim("roles",List.of("ADMIN")).build();assertThrows(Exception.class,()->s.list(jwt));assertThrows(Exception.class,()->s.history(UUID.randomUUID(),jwt));assertThrows(Exception.class,()->s.update(UUID.randomUUID(),input("1","2","5"),UUID.randomUUID().toString(),jwt));verifyNoInteractions(db);}
 @Test void lenderListIsFilteredBySignedIdentity(){var db=mock(DatabaseAccess.class);var s=new LenderRulesService(db,new ObjectMapper());String id="bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1";s.list(officer(id));verify(db).queryForList(contains("WHERE R.lender_id=?"),eq(id));}
 @Test void otherLenderProductIsHiddenBeforeAnyWrite(){var db=mock(DatabaseAccess.class);var s=new LenderRulesService(db,new ObjectMapper());var jwt=officer("bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1");var id=UUID.randomUUID();var ex=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->s.update(id,input("1","2","5"),UUID.randomUUID().toString(),jwt));assertEquals(404,ex.getStatusCode().value());verify(db).queryForList(contains("WHERE product_id=? AND lender_id=?"),eq(String.class),eq(id.toString()),eq(jwt.getClaimAsString("lenderId")));verifyNoMoreInteractions(db);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->s.history(id,jwt));}
 @Test void invalidLenderIdentityAndServiceClientsAreDenied(){var db=mock(DatabaseAccess.class);var s=new LenderRulesService(db,new ObjectMapper());assertThrows(Exception.class,()->s.list(officer("invalid")));var client=Jwt.withTokenValue("unit").header("alg","RS256").subject("client").claim("roles",List.of("LENDER_OFFICER")).claim("lenderId","bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1").claim("client_id","machine").build();assertThrows(Exception.class,()->s.list(client));verifyNoInteractions(db);}
}
